import React from "react";
import { Link } from "react-router-dom";

export default function Navbar() {
  return (
    <div style={navStyle}>
      <h3 style={{ margin: 0 }}>Daily Tracker</h3>

      <div style={linkContainer}>
        <Link to="/" style={linkStyle}>Dashboard</Link>
        <Link to="/report" style={linkStyle}>Report</Link>
        <Link to="/streak" style={linkStyle}>Streak</Link>
        <Link to="/routine" style={linkStyle}>Routine</Link>
      </div>
    </div>
  );
}

const navStyle = {
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center",
  padding: "12px 20px",
  background: "#111",
  color: "#fff",
  flexWrap: "wrap"
};

const linkContainer = {
  display: "flex",
  gap: "15px",
  flexWrap: "wrap"
};

const linkStyle = {
  color: "#fff",
  textDecoration: "none",
  fontWeight: "bold"
};
